{
  "framing_conflicto_politico_vs_tecnologico": {
    "definicion": "Técnica que transforma un asunto esencialmente técnico en una disputa política, resaltando alineaciones partidarias y valores ideológicos en lugar de los aspectos científicos o de ingeniería. Se utilizan vocablos como “lucha”, “batalla” y “ideología” para que la audiencia perciba el tema como un conflicto de poder y no como una cuestión de desarrollo tecnológico.",
    "ejemplo": "Cobertura de la normativa de inteligencia artificial en EE.UU. (marzo 2024) donde los medios presentaron la propuesta de la Comisión Federal de Comercio como una “guerra entre demócratas progresistas y republicanos conservadores” en vez de centrarse en los riesgos técnicos de la IA.",
    "como_detectarla": "1. Identificar si el tema central es tecnológico o científico. 2. Analizar si el discurso privilegia la polarización política sobre datos técnicos. 3. Verificar la presencia de términos de conflicto (batalla, lucha, partidista) que sustituyen al análisis técnico."
  },
  "framing_noticias_locales_culturales": {
    "definicion": "Enfoque que sitúa hechos locales o culturales como marco principal para interpretar una noticia, resaltando identidades regionales, tradiciones y símbolos comunitarios para generar afinidad y, a veces, distanciamiento con audiencias externas.",
    "ejemplo": "Reportaje de la cadena Televisa (abril 2024) sobre el Festival de la Guelaguetza en Oaxaca, presentado como “el corazón resistente de la cultura mexicana frente a la violencia urbana”, enfatizando la identidad local y minimizando la cobertura de problemas de seguridad en la región.",
    "como_detectarla": "1. Detectar la presencia de referencias geográficas o culturales específicas. 2. Evaluar si el relato usa esos elementos como lente dominante para interpretar la noticia. 3. Observar la omisión de contextos más amplios que podrían equilibrar la visión local."
  },
  "enfoque_selectivo_controversias_politicas": {
    "definicion": "Selección deliberada de ciertos argumentos, actores o datos dentro de una controversia política, destacando los aspectos que favorecen una narrativa y suprimiendo aquellos que la contradicen, creando una visión parcial del debate.",
    "ejemplo": "Cobertura de la reforma laboral española (febrero 2024) en varios periódicos nacionales, que resaltó exclusivamente las protestas de los sindicatos y omitió la mayoría de los testimonios de empresarios que apoyaban la medida.",
    "como_detectarla": "1. Comparar la información presentada con fuentes independientes para identificar lagunas. 2. Señalar qué voces o datos aparecen repetidamente y cuáles están ausentes. 3. Analizar si la selección favorece una posición ideológica específica."
  },
  "infotainment_figuras_publicas": {
    "definicion": "Fusión de información y entretenimiento centrada en personalidades públicas, donde la narrativa se construye alrededor de anécdotas, humor y dramatismo para atraer audiencia, a menudo simplificando o distorsionando el contenido sustancial.",
    "ejemplo": "Programa nocturno “En la Sala” (mayo 2024) donde el presentador comenta la nueva política de salud del presidente con chistes, sketches y entrevistas estilo reality, convirtiendo la discusión de la reforma en un espectáculo cómico.",
    "como_detectarla": "1. Identificar la presencia de elementos de entretenimiento (humor, dramatización, estilo talk‑show). 2. Evaluar si la figura pública ocupa el centro del mensaje en lugar del tema. 3. Verificar la profundidad de la información; la escasez de datos sustantivos indica infotainment."
  },
  "framing_amenaza_social_citas_polemicas": {
    "definicion": "Estrategia que construye una percepción de peligro social utilizando citas controvertidas o fuera de contexto de autoridades, expertos o influencers, para dramatizar el tema y generar miedo o indignación en la audiencia.",
    "ejemplo": "Artículo del diario El País (junio 2024) que cita textualmente a un influencer de TikTok diciendo: “Los inmigrantes están destruyendo nuestras ciudades”, usado como eje para titular la pieza “La invasión que amenaza nuestra seguridad”. La cita fue sacada de un video satírico y descontextualizada.",
    "como_detectarla": "1. Rastrear la fuente original de la cita y verificar su contexto completo. 2. Analizar si la cita se utiliza como prueba central de una amenaza social. 3. Examinar la carga emocional del lenguaje que rodea la cita; un tono alarmista sugiere framing de amenaza."
  }
}
